import{_ as e,o as n,c as r,ag as a}from"./chunks/framework.D9ghT4bC.js";const y=JSON.parse('{"title":"Unciv Basic Terminology","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Guides/Unciv-basics/index.md","filePath":"Community/Guides/Unciv-basics/index.md"}'),i={name:"Community/Guides/Unciv-basics/index.md"};function l(d,t,s,o,c,g){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="unciv-basic-terminology" tabindex="-1">Unciv Basic Terminology <a class="header-anchor" href="#unciv-basic-terminology" aria-label="Permalink to &quot;Unciv Basic Terminology&quot;">​</a></h1><blockquote><p>Authors: Unciv Tieba &amp; Civ V Tieba communities</p><p>Date: 2026-02-12</p></blockquote><h2 id="terms-abbreviations" tabindex="-1">Terms / Abbreviations <a class="header-anchor" href="#terms-abbreviations" aria-label="Permalink to &quot;Terms / Abbreviations&quot;">​</a></h2><p>Chinese players often use shorthand names (e.g. &quot;巴弓&quot; for Babylonian Bowman). This page only lists special abbreviations/terms.</p><h3 id="english-abbreviations" tabindex="-1">English abbreviations <a class="header-anchor" href="#english-abbreviations" aria-label="Permalink to &quot;English abbreviations&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Abbr</th><th style="text-align:center;">Full</th><th style="text-align:center;">Meaning</th></tr></thead><tbody><tr><td style="text-align:center;">T</td><td style="text-align:center;">Turn</td><td style="text-align:center;">Turn</td></tr><tr><td style="text-align:center;">UU</td><td style="text-align:center;">Unique Unit</td><td style="text-align:center;">Unique unit</td></tr><tr><td style="text-align:center;">UA</td><td style="text-align:center;">Unique Ability</td><td style="text-align:center;">Unique ability</td></tr><tr><td style="text-align:center;">UB</td><td style="text-align:center;">Unique Building</td><td style="text-align:center;">Unique building</td></tr><tr><td style="text-align:center;">UI</td><td style="text-align:center;">Unique Improvement</td><td style="text-align:center;">Unique improvement</td></tr><tr><td style="text-align:center;">MOD</td><td style="text-align:center;">Modification</td><td style="text-align:center;">A game extension, i.e. a mod</td></tr><tr><td style="text-align:center;">TJ</td><td style="text-align:center;">—</td><td style="text-align:center;">&quot;Eunuch&quot; (tj) — quitting a game before finishing</td></tr><tr><td style="text-align:center;">G</td><td style="text-align:center;">Gold</td><td style="text-align:center;">Gold / cash</td></tr><tr><td style="text-align:center;">AI</td><td style="text-align:center;">artificial intelligence</td><td style="text-align:center;">Computer players</td></tr><tr><td style="text-align:center;">RA</td><td style="text-align:center;">Research Agreement</td><td style="text-align:center;">Research agreement</td></tr><tr><td style="text-align:center;">GPT</td><td style="text-align:center;">Gold Per Turn</td><td style="text-align:center;">Gold per turn</td></tr><tr><td style="text-align:center;">SL</td><td style="text-align:center;">Save/Load (Ciallo~)</td><td style="text-align:center;">Saving and loading</td></tr></tbody></table><h3 id="wonder-shorthand-chinese-community" tabindex="-1">Wonder shorthand (Chinese community) <a class="header-anchor" href="#wonder-shorthand-chinese-community" aria-label="Permalink to &quot;Wonder shorthand (Chinese community)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Shorthand</th><th style="text-align:center;">Wonder</th></tr></thead><tbody><tr><td style="text-align:center;">弓庙/粮庙/吃货庙</td><td style="text-align:center;">Temple of Artemis</td></tr><tr><td style="text-align:center;">经验门</td><td style="text-align:center;">Brandenburg Gate</td></tr><tr><td style="text-align:center;">齐秦</td><td style="text-align:center;">Chichen Itza</td></tr><tr><td style="text-align:center;">面包山</td><td style="text-align:center;">Uluru</td></tr><tr><td style="text-align:center;">冰淇淋山</td><td style="text-align:center;">Mount Kailash</td></tr><tr><td style="text-align:center;">科研火山</td><td style="text-align:center;">Krakatoa</td></tr><tr><td style="text-align:center;">宗教山</td><td style="text-align:center;">Sinai / Uluru / Mount Kailash etc. — natural wonders granting lots of Faith</td></tr></tbody></table><h3 id="unit-shorthand" tabindex="-1">Unit shorthand <a class="header-anchor" href="#unit-shorthand" aria-label="Permalink to &quot;Unit shorthand&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Shorthand</th><th style="text-align:center;">Unit</th></tr></thead><tbody><tr><td style="text-align:center;">猴子/狗 (monkey/dog)</td><td style="text-align:center;">Scout</td></tr><tr><td style="text-align:center;">小矛/叉叉 (little spear)</td><td style="text-align:center;">Spearman</td></tr><tr><td style="text-align:center;">棒子/鸡腿 (club)</td><td style="text-align:center;">Warrior</td></tr><tr><td style="text-align:center;">妹子 (girl)</td><td style="text-align:center;">Worker</td></tr><tr><td style="text-align:center;">小弓 (little bow)</td><td style="text-align:center;">Archer</td></tr><tr><td style="text-align:center;">车射/车车 (chariot)</td><td style="text-align:center;">Chariot Archer</td></tr><tr><td style="text-align:center;">大仙 (big immortal)</td><td style="text-align:center;">Great Prophet</td></tr><tr><td style="text-align:center;">小仙 (little immortal)</td><td style="text-align:center;">Missionary</td></tr></tbody></table><h3 id="building-shorthand" tabindex="-1">Building shorthand <a class="header-anchor" href="#building-shorthand" aria-label="Permalink to &quot;Building shorthand&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Shorthand</th><th style="text-align:center;">Building</th></tr></thead><tbody><tr><td style="text-align:center;">小庙 (little shrine)</td><td style="text-align:center;">Shrine</td></tr><tr><td style="text-align:center;">大庙 (big shrine)</td><td style="text-align:center;">Temple</td></tr></tbody></table><h3 id="religion-shorthand" tabindex="-1">Religion shorthand <a class="header-anchor" href="#religion-shorthand" aria-label="Permalink to &quot;Religion shorthand&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Shorthand</th><th style="text-align:center;">Meaning</th></tr></thead><tbody><tr><td style="text-align:center;">沙神 (sand god)</td><td style="text-align:center;">Desert Folklore</td></tr></tbody></table><h3 id="common-terms" tabindex="-1">Common terms <a class="header-anchor" href="#common-terms" aria-label="Permalink to &quot;Common terms&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Term</th><th style="text-align:center;">Meaning</th></tr></thead><tbody><tr><td style="text-align:center;">爆铺 (wide)</td><td style="text-align:center;">Many cities, developing national strength through numbers</td></tr><tr><td style="text-align:center;">精铺 (tall)</td><td style="text-align:center;">Few cities, focusing on a small number of high-quality cities</td></tr><tr><td style="text-align:center;">魔王流 (demon king)</td><td style="text-align:center;">Pushing forward while tanking lots of unhappiness</td></tr><tr><td style="text-align:center;">蘑菇 (mushroom)</td><td style="text-align:center;">An AI/player that doesn&#39;t expand, just develops — like a mushroom waiting to be picked</td></tr><tr><td style="text-align:center;">种田 (farming)</td><td style="text-align:center;">Focusing on developing your own strength</td></tr><tr><td style="text-align:center;">骗宣 (trick-war)</td><td style="text-align:center;">Trading per-turn resources for an AI&#39;s cash, then declaring war so you keep the cash and the AI gets nothing</td></tr><tr><td style="text-align:center;">买宣 (buy-war)</td><td style="text-align:center;">Paying an AI to declare war on someone else</td></tr><tr><td style="text-align:center;">背刺 (backstab)</td><td style="text-align:center;">Turning hostile/declaring war after long friendship or neutrality</td></tr><tr><td style="text-align:center;">开门 (opening)</td><td style="text-align:center;">Unlocking a policy tree (with its opener effect)</td></tr><tr><td style="text-align:center;">关门 (closing)</td><td style="text-align:center;">Completing all policies of a tree (with its finisher effect)</td></tr><tr><td style="text-align:center;">刮刮乐 (scratch lotto)</td><td style="text-align:center;">Repeatedly pillaging by having workers repair improvements</td></tr><tr><td style="text-align:center;">勾引大法 (lure trick)</td><td style="text-align:center;">Using a worker to bait enemy units onto a tile, then surrounding them</td></tr><tr><td style="text-align:center;">自主左二 etc.</td><td style="text-align:center;">Shorthand for the 2nd policy from the left/middle/right of a policy tree</td></tr><tr><td style="text-align:center;">锤子 (hammer)</td><td style="text-align:center;">Production</td></tr><tr><td style="text-align:center;">瓶子 (bottle)</td><td style="text-align:center;">Science</td></tr><tr><td style="text-align:center;">鸽子 (dove)</td><td style="text-align:center;">Faith</td></tr><tr><td style="text-align:center;">坐城 (sit city)</td><td style="text-align:center;">Founding a city</td></tr></tbody></table>',16)])])}const x=e(i,[["render",l]]);export{y as __pageData,x as default};
